/*! Локальная заглушка Bootstrap JS компонентов для КАРКАС */
window.bootstrap = {
  Modal: function(el) {
    this.show = function() { el.classList.add('show'); el.style.display='block'; document.body.classList.add('modal-open'); };
    this.hide = function() { el.classList.remove('show'); el.style.display='none'; document.body.classList.remove('modal-open'); };
  },
  Dropdown: function(el) { return { toggle: function() {} }; }
};
